"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[8970],{18970:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/change.png\\"\\n          title=\\"변신\\"\\n          author=\\"히가시노 게이고\\"\\n          publisher=\\"창해\\"\\n          publishedDate=\\"2005-07-27\\"\\n          isbn=\\"9788979196856\\"\\n          rating=4\\n          tags=\\"thriller\\"\\n        />\\n</center>\\n\\n## Review\\n뇌 이식 후 점점 달라지는 자신의 모습을 보며 주인공도 스스로 혼란에 빠진다.  \\n식성도 바뀌었고, 차분하던 성격이 분노를 통제하기 힘든 성격으로 바뀌었다.  \\n그림에 대한 재능과 흥미도 잃었고, 연인에 대한 애정도 없어졌다.  \\n<br>\\n이러한 혼돈 속에서 주인공은 ```뇌```의 주인이 누구인지 추적한다.  \\n이후 모든 걸 깨달은 주인공이 내린 결정이 조금 씁쓸하다.  \\n<br>\\n독서 모임에서 이 책을 리뷰한 적이 있다.  \\n```뇌```를 바꾸면 그게 나인가, 뇌의 주인인가에 대한 다른 사람의 의견이 궁금했다.  \\n<br>\\n최근에는 <mark>사소한 변화</mark>라는 제목으로 재출판했는데, ```사소한 변화```라는 제목이 이 작품과 더욱 잘 맞는 것 같아서 마음에 든다.\\n<br>\\n생각해 볼 거리가 있는 작품이라 마음에 든다.\\n"}')}}]);